arguments.command:
cat > /tmp/test3.pl <<'EOF'
open(F, "/app/regex.txt"); my $p = <F>; chomp $p;
my @lines = (
  "ip inside date-ish 1.2.3.4-2020-05-06",            # hyphen adjacency: IP followed by '-' ok? date preceded by '-' ok -> 2020-05-06
  "1.2.3.4 date 2020-1-05",                            # single-digit month invalid -> none
  "1.2.3.4 date 2020-01-5",                            # single-digit day invalid -> none
  "12020-01-05 1.2.3.4",                               # 5-digit prefix year: \d{4} preceded by digit -> none
  "1.2.3.400 2020-01-05",                              # 400 not valid octet, but 1.2.3.40? '1.2.3.40' followed by '0'... blocked -> none
  "11.2.3.4 date 2020-03-31",                          # -> match
  "1.2.3.4:8080 2020-07-31",                           # colon after ip fine -> match
  "2020-04-31 1.2.3.4 2020-04-30",                     # -> 2020-04-30
  "2020-02-29 1.2.3.4",                                # Feb 29 allowed -> match
  "text 999.1.1.1 2020-01-01",                         # 999 invalid... but '99.1.1.1' preceded by 9 (alnum) -> blocked -> none
);
for my $l (@lines) {
  if ($l =~ /$p/m) { print "MATCH: $1  <- $l\n"; } else { print "none   <- $l\n"; }
}
EOF
perl /tmp/test3.pl
